import { describe, it } from "vitest";

// Premium examples use a newcomer (0 years) on their first quote unless stated:
// premium = policy base + item surcharges + 10 % first insurance + 5 G fee, rounded up.
describe("claim office scenario", () => {
  describe("quote: base premiums", () => {
    it.todo("empty item list -> premium 5 G (only the processing fee)");
    it.todo("sword (100 G base) -> premium 115 G");
    it.todo("amulet (60 G base) -> premium 71 G");
    it.todo("staff (80 G base) -> premium 93 G");
    it.todo("potion (40 G base) -> premium 49 G");
    it.todo("1 rune (25 G base) -> 32.5 G rounded up to premium 33 G");
    it.todo("1 moonstone (25 G base) -> premium 33 G");
    it.todo("2 runes (50 G base) -> premium 60 G");
    it.todo("3 runes (60 G block base) -> premium 71 G");
    it.todo("4 runes (100 G base, no block) -> premium 115 G");
    it.todo("7 runes (175 G base) -> 197.5 G rounded up to premium 198 G");
    it.todo("2 runes + 1 moonstone (75 G base, different types) -> 87.5 G rounded up to premium 88 G");
    it.todo("3 runes + 3 moonstones (120 G base, two blocks) -> premium 137 G");
  });

  describe("quote: premium modifiers", () => {
    it.todo("newcomer with cursed sword (steel, enchantment 3) -> premium 165 G");
    it.todo("cursed surcharge applies only to the cursed item: cursed sword + plain amulet -> 210 G + 16 G first insurance + 5 G = 231 G");
    it.todo("sword with enchantment 4, not cursed -> no surcharge, premium 115 G");
    it.todo("sword with exactly enchantment 5 -> high-enchantment surcharge, premium 145 G");
    it.todo("cursed sword with exactly enchantment 5 -> both surcharges, premium 195 G");
    it.todo("customer with 1 year -> no loyalty discount, sword premium 115 G");
    it.todo("customer with exactly 2 years -> loyalty discount, sword premium 95 G");
    it.todo("second quote in a scenario gets 15 % follow-up discount: plain sword quoted twice -> 115 G then 100 G");
    it.todo("long-standing customer (3 years), second quote, cursed sword enchantment 7 -> premium 160 G (first insurance still applies)");
  });

  describe("claim: reimbursement", () => {
    it.todo("steel sword enchantment 3, damage 500 G -> payout 400 G, remaining cap 1600 G");
    it.todo("rune, damage 200 G -> payout 100 G, remaining cap 400 G");
    it.todo("dragon sword exactly enchantment 8, damage 1000 G -> payout 400 G");
    it.todo("dragon sword enchantment 9, damage 1000 G -> payout 400 G (50 % rule wins)");
    it.todo("dragon sword enchantment 5, damage 800 G -> payout 700 G");
    it.todo("steel sword enchantment 9, damage 1000 G -> payout 400 G");
    it.todo("deductible per damaged item: sword 500 G + amulet 300 G -> payout 600 G, remaining cap 2600 G");
    it.todo("two insured swords both damaged 500 G -> each has own deductible, payout 800 G, remaining cap 3200 G (cap 4000 G)");
    it.todo("payout 350.5 G is rounded down: steel sword enchantment 9, damage 901 G -> payout 350 G");
    it.todo("intermediate fractions kept: two enchantment-9 swords damaged 901 G each -> payout 701 G");
  });

  describe("claim: cap", () => {
    it.todo("sword + amulet -> cap 3200 G: amulet damage 300 G -> payout 200 G, remaining cap 3000 G");
    it.todo("cursed sword cap is based on insurance value 1000 G -> cap 2000 G: damage 500 G -> remaining cap 1600 G");
    it.todo("sword + 3 runes -> insurance sum 1750 G, cap 3500 G: rune damage 200 G -> remaining cap 3400 G");
    it.todo("two successive 1500 G sword claims -> payout 1400 G / remaining 600 G, then payout 600 G / remaining 0 G");
  });

  describe("rejections (runScenario throws an Error)", () => {
    it.todo("quote with unknown item type 'broomstick' -> throws");
    it.todo("claim damage to an amulet when only a sword is insured -> throws");
    it.todo("claim damage with unknown item type -> throws");
    it.todo("claim damage with amount -200 -> throws");
    it.todo("claim with two sword damages but only one sword insured -> throws");
  });
});
EOF
