const PROCESSING_FEE = 5;
const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
};
const PERCENT = 100;
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;

function policyBasePremium(items: Item[]): number {
  return items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
}

function premium(items: Item[]): number {
  const policyBase = policyBasePremium(items);
  return Math.ceil((policyBase * (PERCENT + FIRST_INSURANCE_SURCHARGE_PERCENT)) / PERCENT + PROCESSING_FEE);
}

export function runScenario(scenario: Scenario): { results: QuoteResult[] } {
  return { results: scenario.steps.map((step) => ({ premium: premium(step.items) })) };
}

