  if (index < 0) {
    throw new Error(`Damaged item is not covered by the policy: ${damage.itemType}`);
  }
  return undamagedItems.splice(index, 1)[0];
}

function coveredDamages(policy: Policy, damages: Damage[]): { item: Item; amount: number }[] {
  const undamagedItems = [...policy.items];
  return damages.map((damage) => {
    rejectNegativeAmount(damage);
    return { item: takeDamagedItem(undamagedItems, damage), amount: damage.amount };
  });
}

function reimbursement(item: Item, amount: number): number {
  return amount * reimbursedShare(item) - DEDUCTIBLE;
}

function roundPayoutInMhpcoFavor(amount: number): number {
  return Math.floor(amount);
}

function assessedPayout(policy: Policy, damages: Damage[]): number {
  const total = coveredDamages(policy, damages).reduce((sum, { item, amount }) => sum + reimbursement(item, amount), 0);
  return roundPayoutInMhpcoFavor(total);
}

export function settleClaim(policy: Policy, damages: Damage[]): number {
  const payout = Math.min(assessedPayout(policy, damages), policy.remainingCap);
  policy.remainingCap -= payout;
  return payout;
}
import type { Item } from "./item.js";

const COMPONENT_INSURANCE_VALUE = 250;
const COMPONENT_BASE_PREMIUM = 25;
const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;
interface ItemPrice {
  insuranceValue: number;
  basePremium: number;
}

const MAIN_ITEM_PRICES: Record<string, ItemPrice> = {
  sword: { insuranceValue: 1000, basePremium: 100 },
  amulet: { insuranceValue: 600, basePremium: 60 },
  staff: { insuranceValue: 800, basePremium: 80 },
  potion: { insuranceValue: 400, basePremium: 40 },
};
const COMPONENT_TYPES = ["rune", "moonstone"];

function isComponent(item: Item): boolean {
  return COMPONENT_TYPES.includes(item.type);
}

function mainItemPrice(item: Item): ItemPrice {
  const price = MAIN_ITEM_PRICES[item.type];
  if (!price) {
    throw new Error(`Unknown item type: ${item.type}`);
  }
  return price;
}

function itemInsuranceValue(item: Item): number {
  return isComponent(item) ? COMPONENT_INSURANCE_VALUE : mainItemPrice(item).insuranceValue;
}

export function insuranceSum(items: Item[]): number {
  return items.reduce((sum, item) => sum + itemInsuranceValue(item), 0);
}

export function itemBasePremium(item: Item): number {
  return isComponent(item) ? COMPONENT_BASE_PREMIUM : mainItemPrice(item).basePremium;
}

function componentsBasePremium(count: number): number {
  return count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * COMPONENT_BASE_PREMIUM;
}

export function policyBasePremium(items: Item[]): number {
  const mainItems = items.filter((item) => !isComponent(item));
  const mainItemsBase = mainItems.reduce((sum, item) => sum + itemBasePremium(item), 0);
  const componentsBase = COMPONENT_TYPES.reduce(
    (sum, type) => sum + componentsBasePremium(items.filter((item) => item.type === type).length),
    0,
  );
  return mainItemsBase + componentsBase;
}
import type { Customer } from "./customer.js";
import type { Item } from "./item.js";
import { itemBasePremium, policyBasePremium } from "./priceList.js";

const PROCESSING_FEE = 5;
const PERCENT = 100;
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
const CURSED_SURCHARGE_PERCENT = 50;
const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
const HIGH_ENCHANTMENT_LEVEL = 5;
const LOYALTY_DISCOUNT_PERCENT = 20;
const LOYALTY_YEARS = 2;
const FOLLOW_UP_DISCOUNT_PERCENT = 15;

function roundPremiumInMhpcoFavor(amount: number): number {
  return Math.ceil(amount);
}

function percentOf(amount: number, percent: number): number {
  return (amount * percent) / PERCENT;
}

function isHighlyEnchanted(item: Item): boolean {
  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
}

function itemRiskSurcharge(item: Item): number {
  const cursedPercent = item.cursed ? CURSED_SURCHARGE_PERCENT : 0;
  const enchantmentPercent = isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE_PERCENT : 0;
  return percentOf(itemBasePremium(item), cursedPercent + enchantmentPercent);
}

function isLongStandingCustomer(customer: Customer): boolean {
  return customer.yearsWithMHPCO >= LOYALTY_YEARS;
}

function policyWideModifierPercent(customer: Customer, previousContracts: number): number {
  const loyaltyPercent = isLongStandingCustomer(customer) ? -LOYALTY_DISCOUNT_PERCENT : 0;
  const followUpPercent = previousContracts > 0 ? -FOLLOW_UP_DISCOUNT_PERCENT : 0;
  return FIRST_INSURANCE_SURCHARGE_PERCENT + loyaltyPercent + followUpPercent;
}

export function quotePremium(items: Item[], customer: Customer, previousContracts: number): number {
  const policyBase = policyBasePremium(items);
  const itemSurcharges = items.reduce((sum, item) => sum + itemRiskSurcharge(item), 0);
  const policyModifiers = percentOf(policyBase, policyWideModifierPercent(customer, previousContracts));
  return roundPremiumInMhpcoFavor(policyBase + itemSurcharges + policyModifiers + PROCESSING_FEE);
}
